1	import { useState, useCallback, useEffect } from "react";
2	import type {
3	  ActionFunctionArgs,
4	  HeadersFunction,
5	  LoaderFunctionArgs,
6	} from "react-router";
7	import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
8	import { useAppBridge } from "@shopify/app-bridge-react";
9	import { authenticate } from "../shopify.server";
10	import { boundary } from "@shopify/shopify-app-react-router/server";
11	import db from "../db.server";
12	import { getShopSubscription } from "../billing.server";
13	import { PLAN_LIMITS, UNLIMITED } from "../plans";
14	import {
15	  Page,
16	  Layout,
17	  Card,
18	  BlockStack,
19	  InlineStack,
20	  InlineGrid,
21	  Text,
22	  Badge,
23	  Button,
24	  TextField,
25	  Select,
26	  Modal,
27	  IndexTable,
28	  useIndexResourceState,
29	  EmptyState,
30	  Divider,
31	  Box,
32	  Tooltip,
33	  Checkbox,
34	  Banner,
35	} from "@shopify/polaris";
36	import { PlusIcon, DeleteIcon, EditIcon, ViewIcon, HideIcon } from "@shopify/polaris-icons";
37	
38	const DAYS_OPTIONS = [
39	  { label: "Monday", value: "Mon" },
40	  { label: "Tuesday", value: "Tue" },
41	  { label: "Wednesday", value: "Wed" },
42	  { label: "Thursday", value: "Thu" },
43	  { label: "Friday", value: "Fri" },
44	  { label: "Saturday", value: "Sat" },
45	  { label: "Sunday", value: "Sun" },
46	];
47	
48	export const loader = async ({ request }: LoaderFunctionArgs) => {
49	  const { session } = await authenticate.admin(request);
50	  const shop = session.shop;
51	
52	  const [rules, zones, subscription] = await Promise.all([
53	    db.deliveryRule.findMany({
54	      where: { shop },
55	      orderBy: { priority: "asc" },
56	    }),
57	    db.zipCode.findMany({
58	      where: { shop, zone: { not: null } },
59	      select: { zone: true },
60	      distinct: ["zone"],
61	    }),
62	    getShopSubscription(shop),
63	  ]);
64	
65	  return {
66	    rules,
67	    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
68	    subscription,
69	  };
70	};
71	
72	export const action = async ({ request }: ActionFunctionArgs) => {
73	  const { session } = await authenticate.admin(request);
74	  const shop = session.shop;
75	  const formData = await request.formData();
76	  const intent = formData.get("intent");
77	
78	  if (intent === "create" || intent === "update") {
79	    const id = String(formData.get("id") || "");
80	    const name = String(formData.get("name") || "").trim();
81	    const zone = String(formData.get("zone") || "").trim() || null;
82	    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
83	    const minOrderAmount = formData.get("minOrderAmount")
84	      ? parseFloat(String(formData.get("minOrderAmount")))
85	      : null;
86	    const deliveryFee = formData.get("deliveryFee")
87	      ? parseFloat(String(formData.get("deliveryFee")))
88	      : null;
89	    const freeShippingAbove = formData.get("freeShippingAbove")
90	      ? parseFloat(String(formData.get("freeShippingAbove")))
91	      : null;
92	    const estimatedDays =
93	      String(formData.get("estimatedDays") || "").trim() || null;
94	    const cutoffTime =
95	      String(formData.get("cutoffTime") || "").trim() || null;
96	    const daysOfWeek =
97	      String(formData.get("daysOfWeek") || "").trim() || null;
98	    const priority = parseInt(String(formData.get("priority") || "0"), 10);
99	
100	    if (!name) return { error: "Rule name is required." };
101	
102	    const data = {
103	      name,
104	      zone,
105	      zipCodes,
106	      minOrderAmount,
107	      deliveryFee,
108	      freeShippingAbove,
109	      estimatedDays,
110	      cutoffTime,
111	      daysOfWeek,
112	      priority,
113	    };
114	
115	    if (intent === "update" && id) {
116	      try {
117	        const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
118	        if (!existing) return { error: "Rule not found." };
119	        await db.deliveryRule.update({ where: { id }, data });
120	        return { success: true, action: "updated" };
121	      } catch {
122	        return { error: "Failed to update rule." };
123	      }
124	    } else {
125	      // Plan-gating: check limits before creating a new rule
126	      const subscription = await getShopSubscription(shop);
127	      const { maxDeliveryRules, label: planLabel } = subscription.limits;
128	
129	      if (maxDeliveryRules === 0) {
130	        return {
131	          error:
132	            "Delivery rules are not available on the Free plan. Upgrade to Starter or Pro.",
133	        };
134	      }
135	
136	      if (maxDeliveryRules < UNLIMITED) {
137	        const currentCount = await db.deliveryRule.count({ where: { shop } });
138	        if (currentCount >= maxDeliveryRules) {
139	          return {
140	            error: `You've reached the ${maxDeliveryRules} delivery rule limit on the ${planLabel} plan. Upgrade to Pro for unlimited rules.`,
141	          };
142	        }
143	      }
144	
145	      await db.deliveryRule.create({ data: { shop, ...data } });
146	      return { success: true, action: "created" };
147	    }
148	  }
149	
150	  if (intent === "delete") {
151	    const id = String(formData.get("id"));
152	    try {
153	      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
154	      if (!existing) return { error: "Rule not found." };
155	      await db.deliveryRule.delete({ where: { id } });
156	      return { success: true, action: "deleted" };
157	    } catch {
158	      return { error: "Failed to delete rule." };
159	    }
160	  }
161	
162	  if (intent === "toggle") {
163	    const id = String(formData.get("id"));
164	    const isActive = formData.get("isActive") === "true";
165	    try {
166	      const existing = await db.deliveryRule.findFirst({ where: { id, shop } });
167	      if (!existing) return { error: "Rule not found." };
168	      await db.deliveryRule.update({
169	        where: { id },
170	        data: { isActive: !isActive },
171	      });
172	      return { success: true, action: "toggled" };
173	    } catch {
174	      return { error: "Failed to toggle rule." };
175	    }
176	  }
177	
178	  if (intent === "bulk-delete") {
179	    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
180	    if (ids.length === 0) return { error: "No rules selected." };
181	    try {
182	      await db.deliveryRule.deleteMany({ where: { id: { in: ids }, shop } });
183	      return { success: true, action: "bulk-deleted" };
184	    } catch {
185	      return { error: "Failed to delete rules." };
186	    }
187	  }
188	
189	  if (intent === "bulk-toggle") {
190	    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
191	    const active = formData.get("active") === "true";
192	    if (ids.length === 0) return { error: "No rules selected." };
193	    try {
194	      await db.deliveryRule.updateMany({
195	        where: { id: { in: ids }, shop },
196	        data: { isActive: active },
197	      });
198	      return { success: true, action: active ? "bulk-activated" : "bulk-deactivated" };
199	    } catch {
200	      return { error: "Failed to update rules." };
201	    }
202	  }
203	
204	  return null;
205	};
206	
207	type Rule = {
208	  id: string;
209	  name: string;
210	  zone: string | null;
211	  zipCodes: string | null;
212	  minOrderAmount: number | null;
213	  deliveryFee: number | null;
214	  freeShippingAbove: number | null;
215	  estimatedDays: string | null;
216	  cutoffTime: string | null;
217	  daysOfWeek: string | null;
218	  isActive: boolean;
219	  priority: number;
220	};
221	
222	export default function DeliveryRulesPage() {
223	  const { rules, zones, subscription } = useLoaderData<typeof loader>();
224	  const limits = PLAN_LIMITS[subscription.planTier];
225	  const isFreePlan = limits.maxDeliveryRules === 0;
226	  const hasFiniteLimit = limits.maxDeliveryRules < UNLIMITED && !isFreePlan;
227	  const fetcher = useFetcher<typeof action>();
228	  const shopify = useAppBridge();
229	  const navigate = useNavigate();
230	
231	  const { selectedResources, allResourcesSelected, handleSelectionChange, clearSelection } =
232	    useIndexResourceState(rules as Rule[]);
233	
234	  const [modalOpen, setModalOpen] = useState(false);
235	  const [editingRule, setEditingRule] = useState<Rule | null>(null);
236	  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
237	  const [confirmBulkDeleteOpen, setConfirmBulkDeleteOpen] = useState(false);
238	
239	  // Form state
240	  const [name, setName] = useState("");
241	  const [zone, setZone] = useState("");
242	  const [zipCodes, setZipCodes] = useState("");
243	  const [minOrderAmount, setMinOrderAmount] = useState("");
244	  const [deliveryFee, setDeliveryFee] = useState("");
245	  const [freeShippingAbove, setFreeShippingAbove] = useState("");
246	  const [estimatedDays, setEstimatedDays] = useState("");
247	  const [cutoffTime, setCutoffTime] = useState("");
248	  const [selectedDays, setSelectedDays] = useState<string[]>([
249	    "Mon",
250	    "Tue",
251	    "Wed",
252	    "Thu",
253	    "Fri",
254	  ]);
255	  const [priority, setPriority] = useState("0");
256	
257	  const actionError =
258	    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
259	
260	  const isDeleteLoading =
261	    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "delete";
262	  const isBulkDeleteLoading =
263	    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "bulk-delete";
264	
265	  const resetForm = useCallback(() => {
266	    setName("");
267	    setZone("");
268	    setZipCodes("");
269	    setMinOrderAmount("");
270	    setDeliveryFee("");
271	    setFreeShippingAbove("");
272	    setEstimatedDays("");
273	    setCutoffTime("");
274	    setSelectedDays(["Mon", "Tue", "Wed", "Thu", "Fri"]);
275	    setPriority("0");
276	    setEditingRule(null);
277	  }, []);
278	
279	  const openCreate = useCallback(() => {
280	    resetForm();
281	    setModalOpen(true);
282	  }, [resetForm]);
283	
284	  const openEdit = useCallback((rule: Rule) => {
285	    setEditingRule(rule);
286	    setName(rule.name);
287	    setZone(rule.zone || "");
288	    setZipCodes(rule.zipCodes || "");
289	    setMinOrderAmount(rule.minOrderAmount != null ? String(rule.minOrderAmount) : "");
290	    setDeliveryFee(rule.deliveryFee != null ? String(rule.deliveryFee) : "");
291	    setFreeShippingAbove(
292	      rule.freeShippingAbove != null ? String(rule.freeShippingAbove) : "",
293	    );
294	    setEstimatedDays(rule.estimatedDays || "");
295	    setCutoffTime(rule.cutoffTime || "");
296	    setSelectedDays(rule.daysOfWeek ? rule.daysOfWeek.split(",") : []);
297	    setPriority(String(rule.priority));
298	    setModalOpen(true);
299	  }, []);
300	
301	  const handleSave = useCallback(() => {
302	    const fd = new FormData();
303	    fd.set("intent", editingRule ? "update" : "create");
304	    if (editingRule) fd.set("id", editingRule.id);
305	    fd.set("name", name);
306	    fd.set("zone", zone);
307	    fd.set("zipCodes", zipCodes);
308	    fd.set("minOrderAmount", minOrderAmount);
309	    fd.set("deliveryFee", deliveryFee);
310	    fd.set("freeShippingAbove", freeShippingAbove);
311	    fd.set("estimatedDays", estimatedDays);
312	    fd.set("cutoffTime", cutoffTime);
313	    fd.set("daysOfWeek", selectedDays.join(","));
314	    fd.set("priority", priority);
315	    fetcher.submit(fd, { method: "POST" });
316	  }, [
317	    editingRule,
318	    name,
319	    zone,
320	    zipCodes,
321	    minOrderAmount,
322	    deliveryFee,
323	    freeShippingAbove,
324	    estimatedDays,
325	    cutoffTime,
326	    selectedDays,
327	    priority,
328	    fetcher,
329	  ]);
330	
331	  const doDelete = useCallback(
332	    (id: string) => {
333	      const fd = new FormData();
334	      fd.set("intent", "delete");
335	      fd.set("id", id);
336	      fetcher.submit(fd, { method: "POST" });
337	      setConfirmDeleteId(null);
338	    },
339	    [fetcher],
340	  );
341	
342	  const handleDelete = useCallback(
343	    (id: string) => {
344	      setConfirmDeleteId(id);
345	    },
346	    [],
347	  );
348	
349	  useEffect(() => {
350	    if (fetcher.state === "idle" && fetcher.data) {
351	      if ("success" in fetcher.data && fetcher.data.success) {
352	        const fetcherAction =
353	          "action" in fetcher.data ? fetcher.data.action : "";
354	        if (fetcherAction === "created") {
355	          shopify.toast.show("Rule created");
356	          setModalOpen(false);
357	          resetForm();
358	        } else if (fetcherAction === "updated") {
359	          shopify.toast.show("Rule updated");
360	          setModalOpen(false);
361	          resetForm();
362	        } else if (fetcherAction === "deleted") {
363	          shopify.toast.show("Rule deleted");
364	        } else if (fetcherAction === "toggled") {
365	          shopify.toast.show("Rule status updated");
366	        } else if (fetcherAction === "bulk-deleted") {
367	          shopify.toast.show("Selected rules deleted");
368	          clearSelection();
369	        } else if (fetcherAction === "bulk-activated") {
370	          shopify.toast.show("Selected rules activated");
371	          clearSelection();
372	        } else if (fetcherAction === "bulk-deactivated") {
373	          shopify.toast.show("Selected rules deactivated");
374	          clearSelection();
375	        }
376	      }
377	    }
378	  }, [fetcher.state, fetcher.data, shopify, resetForm, clearSelection]);
379	
380	  const handleToggle = useCallback(
381	    (id: string, isActive: boolean) => {
382	      const fd = new FormData();
383	      fd.set("intent", "toggle");
384	      fd.set("id", id);
385	      fd.set("isActive", String(isActive));
386	      fetcher.submit(fd, { method: "POST" });
387	    },
388	    [fetcher],
389	  );
390	
391	  const toggleDay = useCallback(
392	    (day: string) => {
393	      setSelectedDays((prev) =>
394	        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
395	      );
396	    },
397	    [],
398	  );
399	
400	  const doBulkDelete = useCallback(() => {
401	    const fd = new FormData();
402	    fd.set("intent", "bulk-delete");
403	    fd.set("ids", selectedResources.join(","));
404	    fetcher.submit(fd, { method: "POST" });
405	    setConfirmBulkDeleteOpen(false);
406	  }, [selectedResources, fetcher]);
407	
408	  const handleBulkDelete = useCallback(() => {
409	    setConfirmBulkDeleteOpen(true);
410	  }, []);
411	
412	  const handleBulkToggle = useCallback(
413	    (active: boolean) => {
414	      const fd = new FormData();
415	      fd.set("intent", "bulk-toggle");
416	      fd.set("ids", selectedResources.join(","));
417	      fd.set("active", String(active));
418	      fetcher.submit(fd, { method: "POST" });
419	    },
420	    [selectedResources, fetcher],
421	  );
422	
423	  const zoneOptions = [
424	    { label: "All zones", value: "" },
425	    ...zones.map((z) => ({ label: z, value: z })),
426	  ];
427	
428	  return (
429	    <Page
430	      title="Delivery Rules"
431	      subtitle="Configure delivery fees, minimums, schedules, and conditions per zone"
432	      backAction={{ onAction: () => navigate("/app") }}
433	      primaryAction={
434	        isFreePlan
435	          ? undefined
436	          : {
437	              content: "Add Rule",
438	              icon: PlusIcon,
439	              onAction: openCreate,
440	            }
441	      }
442	    >
443	      <Box paddingBlockEnd="1600">
444	      <Layout>
445	        {isFreePlan && (
446	          <Layout.Section>
447	            <Banner
448	              tone="info"
449	              title="Delivery rules require a paid plan"
450	              action={{
451	                content: "View pricing plans",
452	                url: "/app/pricing",
453	              }}
454	            >
455	              <Text as="p">
456	                Upgrade to the Starter plan or higher to create delivery rules
457	                with custom fees, schedules, and zone conditions.
458	              </Text>
459	            </Banner>
460	          </Layout.Section>
461	        )}
462	        {hasFiniteLimit && (
463	          <Layout.Section>
464	            <InlineStack align="end">
465	              <Badge
466	                tone={
467	                  (rules as Rule[]).length >= limits.maxDeliveryRules
468	                    ? "warning"
469	                    : undefined
470	                }
471	              >
472	                {`${(rules as Rule[]).length}/${limits.maxDeliveryRules} rules used`}
473	              </Badge>
474	            </InlineStack>
475	          </Layout.Section>
476	        )}
477	        <Layout.Section>
478	          <Card padding="0">
479	            {(rules as Rule[]).length === 0 ? (
480	              <EmptyState
481	                heading="No delivery rules yet"
482	                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
483	                action={
484	                  isFreePlan
485	                    ? {
486	                        content: "Upgrade to create rules",
487	                        onAction: () => navigate("/app/pricing"),
488	                      }
489	                    : {
490	                        content: "Create your first rule",
491	                        onAction: openCreate,
492	                      }
493	                }
494	              >
495	                <Text as="p">
496	                  Delivery rules let you set fees, minimum order amounts,
497	                  estimated delivery times, and delivery schedules for different
498	                  zones. Rules are evaluated by priority order.
499	                </Text>
500	              </EmptyState>
501	            ) : (
502	              <IndexTable
503	                resourceName={{ singular: "rule", plural: "rules" }}
504	                itemCount={(rules as Rule[]).length}
505	                selectedItemsCount={allResourcesSelected ? "All" : selectedResources.length}
506	                onSelectionChange={handleSelectionChange}
507	                headings={[
508	                  { title: "Rule Name" },
509	                  { title: "Zone" },
510	                  { title: "Delivery Fee" },
511	                  { title: "Min. Order" },
512	                  { title: "ETA" },
513	                  { title: "Days" },
514	                  { title: "Actions" },
515	                ]}
516	                promotedBulkActions={[
517	                  { content: "Activate", onAction: () => handleBulkToggle(true) },
518	                  { content: "Deactivate", onAction: () => handleBulkToggle(false) },
519	                ]}
520	                bulkActions={[
521	                  { content: "Delete selected", onAction: handleBulkDelete },
522	                ]}
523	              >
524	                {(rules as Rule[]).map((rule, index) => (
525	                  <IndexTable.Row
526	                    id={rule.id}
527	                    key={rule.id}
528	                    selected={selectedResources.includes(rule.id)}
529	                    position={index}
530	                  >
531	                    <IndexTable.Cell>
532	                      <InlineStack gap="200" blockAlign="center">
533	                        <Text as="span" fontWeight="bold">{rule.name}</Text>
534	                        <Badge tone={rule.isActive ? "success" : undefined}>
535	                          {rule.isActive ? "Active" : "Inactive"}
536	                        </Badge>
537	                      </InlineStack>
538	                    </IndexTable.Cell>
539	                    <IndexTable.Cell>{rule.zone || "All"}</IndexTable.Cell>
540	                    <IndexTable.Cell>
541	                      {rule.deliveryFee != null ? `$${rule.deliveryFee.toFixed(2)}` : "Free"}
542	                    </IndexTable.Cell>
543	                    <IndexTable.Cell>
544	                      {rule.minOrderAmount != null ? `$${rule.minOrderAmount.toFixed(2)}` : "—"}
545	                    </IndexTable.Cell>
546	                    <IndexTable.Cell>{rule.estimatedDays || "—"}</IndexTable.Cell>
547	                    <IndexTable.Cell>{rule.daysOfWeek || "All days"}</IndexTable.Cell>
548	                    <IndexTable.Cell>
549	                      {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
550	                      <div onClick={(e) => e.stopPropagation()}>
551	                      <InlineStack gap="200">
552	                        <Tooltip content={rule.isActive ? "Click to deactivate" : "Click to activate"}>
553	                          <Button
554	                            size="slim"
555	                            variant="tertiary"
556	                            tone={rule.isActive ? "success" : undefined}
557	                            onClick={() => handleToggle(rule.id, rule.isActive)}
558	                            icon={rule.isActive ? ViewIcon : HideIcon}
559	                            accessibilityLabel={rule.isActive ? "Deactivate rule" : "Activate rule"}
560	                          />
561	                        </Tooltip>
562	                        <Tooltip content="Edit rule">
563	                          <Button
564	                            size="slim"
565	                            variant="tertiary"
566	                            onClick={() => openEdit(rule)}
567	                            icon={EditIcon}
568	                            accessibilityLabel="Edit"
569	                          />
570	                        </Tooltip>
571	                        <Tooltip content="Delete rule">
572	                          <Button
573	                            size="slim"
574	                            variant="tertiary"
575	                            tone="critical"
576	                            onClick={() => handleDelete(rule.id)}
577	                            icon={DeleteIcon}
578	                            accessibilityLabel="Delete"
579	                          />
580	                        </Tooltip>
581	                      </InlineStack>
582	                      </div>
583	                    </IndexTable.Cell>
584	                  </IndexTable.Row>
585	                ))}
586	              </IndexTable>
587	            )}
588	          </Card>
589	        </Layout.Section>
590	      </Layout>
591	      </Box>
592	
593	      {/* Create / Edit Modal */}
594	      <Modal
595	        open={modalOpen}
596	        onClose={() => {
597	          setModalOpen(false);
598	          resetForm();
599	        }}
600	        title={editingRule ? "Edit Delivery Rule" : "Create Delivery Rule"}
601	        primaryAction={{
602	          content: editingRule ? "Save Changes" : "Create Rule",
603	          onAction: handleSave,
604	        }}
605	        secondaryActions={[
606	          {
607	            content: "Cancel",
608	            onAction: () => {
609	              setModalOpen(false);
610	              resetForm();
611	            },
612	          },
613	        ]}
614	      >
615	        <Modal.Section>
616	          <BlockStack gap="400">
617	            {actionError && <Banner tone="critical">{actionError}</Banner>}
618	
619	            <TextField
620	              label="Rule Name"
621	              value={name}
622	              onChange={setName}
623	              placeholder="e.g. Manhattan Standard Delivery"
624	              autoComplete="off"
625	              helpText="A descriptive name for this delivery rule."
626	            />
627	
628	            <InlineGrid columns={2} gap="300">
629	              <Select
630	                label="Zone"
631	                options={zoneOptions}
632	                value={zone}
633	                onChange={setZone}
634	                helpText="Apply this rule to a specific zone, or all zones."
635	              />
636	              <TextField
637	                label="Priority"
638	                type="number"
639	                value={priority}
640	                onChange={setPriority}
641	                autoComplete="off"
642	                helpText="Lower number = higher priority."
643	              />
644	            </InlineGrid>
645	
646	            <TextField
647	              label="Specific Zip Codes (optional)"
648	              value={zipCodes}
649	              onChange={setZipCodes}
650	              placeholder="10001, 10002, 10003"
