115	/**
116	 * Cancel subscription for a shop and revert to free.
117	 */
118	export async function cancelShopSubscription(shop: string): Promise<void> {
119	  await db.subscription.upsert({
120	    where: { shop },
121	    create: {
122	      shop,
123	      planId: PLAN_FREE,
124	      billingInterval: "monthly",
125	      shopifySubscriptionId: null,
126	      status: "active",
127	    },
128	    update: {
129	      planId: PLAN_FREE,
130	      billingInterval: "monthly",
131	      shopifySubscriptionId: null,
132	      status: "active",
133	    },
134	  });
135	}
